  await ts.stepHost.runStepType(
    'LimitTestChannelValue',
    ts.StepPhase.post,
    ts.PropObj({
      'Veristand': ts.PropObj({
        'ValueToSet': '0',
        'ChannelName': '"Targets/Controller/Simulation Models/Models/Engine Demo/Outports/RPM"',
      }),
      'Limits': ts.PropObj({
        'UseNominalExpr': true,
        'UseThresholdTypeExpr': false,
        'Nominal': 0,
